import { AgentSession as pb } from '@livekit/protocol';
import { describe, expect, it } from 'vitest';
import type { AudioContent, ImageContent } from '../llm/chat_context.js';
import {
  AgentHandoffItem,
  ChatContext,
  FunctionCall,
  FunctionCallOutput,
} from '../llm/chat_context.js';
import type { ModelUsage } from '../metrics/model_usage.js';
import type {
  AgentSessionOptions,
  ResolvedRecordingOptions,
  VoiceOptions,
} from './agent_session.js';
import {
  AgentSessionEventTypes,
  CloseReason,
  createCloseEvent,
  createConversationItemAddedEvent,
  createErrorEvent,
  createFunctionToolsExecutedEvent,
  createSessionUsageUpdatedEvent,
  createUserInputTranscribedEvent,
  createUserStateChangedEvent,
} from './events.js';
import type { AgentSessionUsage } from './index.js';
import { createSessionReport, sessionReportToJSON } from './report.js';

type ReportOptions = AgentSessionOptions &
  Partial<VoiceOptions> & { recordingOptions: ResolvedRecordingOptions };

function baseOptions(): ReportOptions {
  return {
    maxToolSteps: 3,
    userAwayTimeout: 15,
    useTtsAlignedTranscript: true,
    turnHandling: {
      preemptiveGeneration: { enabled: false },
    },
    recordingOptions: {
      audio: false,
      traces: false,
      logs: false,
      transcript: false,
      redaction: false,
      inputDelta: false,
    },
  };
}

function serializeOptions(options: ReportOptions) {
  const report = createSessionReport({
    jobId: 'job',
    roomId: 'room-id',
    room: 'room',
    options,
    events: [],
    chatHistory: ChatContext.empty(),
    enableRecording: false,
    timestamp: 0,
    startedAt: 0,
  });

  const payload = sessionReportToJSON(report);
  return payload.options as Record<string, unknown>;
}

describe('sessionReportToJSON', () => {
  it('serializes interruption and endpointing values from turnHandling', () => {
    const options = baseOptions();
    options.turnHandling = {
      interruption: {
        mode: 'adaptive',
        discardAudioIfUninterruptible: false,
        minDuration: 1200,
        minWords: 2,
      },
      endpointing: {
        minDelay: 900,
        maxDelay: 4500,
      },
    };

    const serialized = serializeOptions(options);
    expect(serialized).toMatchObject({
      allow_interruptions: true,
      discard_audio_if_uninterruptible: false,
      min_interruption_duration: 1200,
      min_interruption_words: 2,
      min_endpointing_delay: 900,
      max_endpointing_delay: 4500,
      max_tool_steps: 3,
    });
  });

  it('prefers turnHandling values over deprecated flat fields', () => {
    const options = baseOptions();
    options.allowInterruptions = false;
    options.discardAudioIfUninterruptible = true;
    options.minInterruptionDuration = 400;
    options.minInterruptionWords = 1;
    options.minEndpointingDelay = 500;
    options.maxEndpointingDelay = 2500;
    options.turnHandling = {
      interruption: {
        mode: 'vad',
        discardAudioIfUninterruptible: false,
        minDuration: 1400,
        minWords: 4,
      },
      endpointing: {
        minDelay: 700,
        maxDelay: 3900,
      },
    };

    const serialized = serializeOptions(options);
    expect(serialized).toMatchObject({
      allow_interruptions: true,
      discard_audio_if_uninterruptible: false,
      min_interruption_duration: 1400,
      min_interruption_words: 4,
      min_endpointing_delay: 700,
      max_endpointing_delay: 3900,
      max_tool_steps: 3,
    });
  });

  it('serializes allow_interruptions from interruption.enabled when present', () => {
    const options = baseOptions();
    options.allowInterruptions = true;
    options.turnHandling = {
      interruption: {
        enabled: false,
        mode: 'adaptive',
      },
    };

    const serialized = serializeOptions(options);
    expect(serialized).toMatchObject({
      allow_interruptions: false,
      max_tool_steps: 3,
    });
  });

  it('falls back to deprecated flat fields when turnHandling values are absent', () => {
    const options = baseOptions();
    options.allowInterruptions = false;
    options.discardAudioIfUninterruptible = false;
    options.minInterruptionDuration = 600;
    options.minInterruptionWords = 3;
    options.minEndpointingDelay = 1000;
    options.maxEndpointingDelay = 5000;

    const serialized = serializeOptions(options);
    expect(serialized).toMatchObject({
      allow_interruptions: false,
      discard_audio_if_uninterruptible: false,
      min_interruption_duration: 600,
      min_interruption_words: 3,
      min_endpointing_delay: 1000,
      max_endpointing_delay: 5000,
      max_tool_steps: 3,
    });
  });

  it('serializes model usage as usage', () => {
    const usage: ModelUsage[] = [
      {
        type: 'tts_usage',
        provider: 'elevenlabs',
        model: 'eleven_flash_v2_5',
        inputTokens: 0,
        outputTokens: 0,
        charactersCount: 42,
        audioDurationMs: 1200,
      },
    ];

    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory: ChatContext.empty(),
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
      modelUsage: usage,
    });

    const payload = sessionReportToJSON(report);
    expect(payload.usage).toEqual([
      {
        type: 'tts_usage',
        provider: 'elevenlabs',
        model: 'eleven_flash_v2_5',
        characters_count: 42,
        audio_duration: 1.2,
      },
    ]);
  });

  it('omits session usage update events from serialized events', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [
        createSessionUsageUpdatedEvent({
          usage: {
            modelUsage: [
              {
                type: 'tts_usage',
                provider: 'elevenlabs',
                model: 'eleven_flash_v2_5',
              },
            ],
          },
          createdAt: 123,
        }),
      ],
      chatHistory: ChatContext.empty(),
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    const payload = sessionReportToJSON(report);
    expect(payload.events).toEqual([]);
  });

  it('serializes events with snake_case keys to match the Python wire format', () => {
    const chatHistory = ChatContext.empty();
    const msg = chatHistory.addMessage({ role: 'user', content: 'hi', createdAt: 5 });

    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [
        createUserStateChangedEvent('listening', 'speaking', 7),
        createUserInputTranscribedEvent({
          transcript: 'hello',
          isFinal: true,
          speakerId: 'spk_1',
          createdAt: 9,
        }),
        createConversationItemAddedEvent(msg, 11),
      ],
      chatHistory,
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    const payload = sessionReportToJSON(report);
    expect(payload.events).toEqual([
      { type: 'user_state_changed', old_state: 'listening', new_state: 'speaking', created_at: 7 },
      {
        type: 'user_input_transcribed',
        transcript: 'hello',
        is_final: true,
        item_id: null,
        speaker_id: 'spk_1',
        language: null,
        created_at: 9,
      },
      {
        type: 'conversation_item_added',
        // chat items expose camelCase via toJSON(); the report layer converts to the
        // snake_case wire shape (e.g. created_at).
        item: {
          id: msg.id,
          type: 'message',
          role: 'user',
          content: ['hi'],
          interrupted: false,
          created_at: 5,
        },
        created_at: 11,
      },
    ]);
  });

  it('serializes function_tools_executed with only the Python event fields', () => {
    const call = FunctionCall.create({ callId: 'call_1', name: 'lookup', args: '{}' });
    const output = FunctionCallOutput.create({
      callId: 'call_1',
      name: 'lookup',
      output: 'ok',
      isError: false,
    });
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [
        createFunctionToolsExecutedEvent({
          functionCalls: [call],
          functionCallOutputs: [output],
          createdAt: 5,
        }),
      ],
      chatHistory: ChatContext.empty(),
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    // hasToolReply and cancelToolReply() are derived, so Python's model_dump() omits them
    expect(sessionReportToJSON(report).events).toEqual([
      {
        type: 'function_tools_executed',
        function_calls: [expect.objectContaining({ call_id: 'call_1' })],
        function_call_outputs: [
          expect.objectContaining({ call_id: 'call_1', reply_required: true }),
        ],
        created_at: 5,
      },
    ]);
  });

  it('includes audio recording and sdk metadata in the report', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory: ChatContext.empty(),
      enableRecording: true,
      timestamp: 0,
      startedAt: 0,
      audioRecordingPath: '/tmp/audio.ogg',
      audioRecordingStartedAt: 1234,
    });

    const payload = sessionReportToJSON(report);
    expect(payload.audio_recording_path).toBe('/tmp/audio.ogg');
    expect(payload.audio_recording_started_at).toBe(1234);
    expect(typeof payload.sdk_version).toBe('string');
    expect((payload.options as Record<string, unknown>).user_away_timeout).toBe(15);
  });

  it('includes chat history and events by default', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [createUserStateChangedEvent('listening', 'speaking', 0)],
      chatHistory: ChatContext.empty(),
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    const payload = sessionReportToJSON(report);
    expect(sessionReportToJSON(report, {})).toEqual(payload);
    expect(sessionReportToJSON(report, { includeChatHistory: true, includeEvents: true })).toEqual(
      payload,
    );
    expect(payload.events).toHaveLength(1);
    // Key order is part of the JSON written to disk, so it must not change.
    expect(Object.keys(payload)).toEqual([
      'job_id',
      'room_id',
      'room',
      'events',
      'audio_recording_path',
      'audio_recording_started_at',
      'options',
      'chat_history',
      'enable_user_data_training',
      'timestamp',
      'usage',
      'sdk_version',
      'agent_name',
      'duration_ms',
      'user_turns',
      'errors',
      'close_reason',
    ]);
  });

  it('adds the session summary fields', () => {
    const chatHistory = ChatContext.empty();
    chatHistory.addMessage({ role: 'user', content: 'hi' });
    chatHistory.addMessage({ role: 'assistant', content: 'hello' });
    chatHistory.addMessage({ role: 'user', content: 'bye' });
    const llmError = {
      type: 'llm_error' as const,
      timestamp: 0,
      label: 'llm',
      error: new Error('x'),
      recoverable: true,
    };
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      agentName: 'support',
      options: baseOptions(),
      events: [
        createErrorEvent(llmError),
        createErrorEvent(llmError),
        createErrorEvent({ ...llmError, type: 'tts_error' as const }),
        createCloseEvent(CloseReason.ERROR),
        createCloseEvent(CloseReason.PARTICIPANT_DISCONNECTED),
      ],
      chatHistory,
      startedAt: 100,
      timestamp: 12_600,
      audioRecordingStartedAt: 100.4,
    });

    // Computed from events and chat history even when those keys are omitted.
    const payload = sessionReportToJSON(report, {
      includeChatHistory: false,
      includeEvents: false,
    });
    expect(payload.agent_name).toBe('support');
    expect(payload.duration_ms).toBe(12500);
    expect(payload.user_turns).toBe(2);
    expect(payload.errors).toEqual({ llm: 2, stt: 0, tts: 1, realtime: 0, interruption: 0 });
    // The last close event wins.
    expect(payload.close_reason).toBe('CR_PARTICIPANT_DISCONNECTED');
    expect(payload).not.toHaveProperty('tags');
  });

  it('sets unknown session summary fields to null', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory: ChatContext.empty(),
    });

    const payload = sessionReportToJSON(report);
    expect(payload.agent_name).toBeNull();
    expect(payload.close_reason).toBeNull();
    expect(payload.user_turns).toBe(0);
    expect(payload.errors).toEqual({ llm: 0, stt: 0, tts: 0, realtime: 0, interruption: 0 });
  });

  it('omits chat history and events when excluded', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [createUserStateChangedEvent('listening', 'speaking', 0)],
      chatHistory: ChatContext.empty(),
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    const full = sessionReportToJSON(report);
    const trimmed = sessionReportToJSON(report, {
      includeChatHistory: false,
      includeEvents: false,
    });
    expect(trimmed).not.toHaveProperty('chat_history');
    expect(trimmed).not.toHaveProperty('events');
    const { chat_history: _chatHistory, events: _events, ...rest } = full;
    expect(trimmed).toEqual(rest);

    expect(sessionReportToJSON(report, { includeEvents: false })).toHaveProperty('chat_history');
    expect(sessionReportToJSON(report, { includeChatHistory: false })).toHaveProperty('events');
  });

  it('serializes chat item timestamps as Unix seconds', () => {
    const chatHistory = ChatContext.empty();
    chatHistory.addMessage({
      role: 'user',
      content: 'hello',
      createdAt: 1787458002314,
    });

    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory,
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    const payload = sessionReportToJSON(report);
    const serializedHistory = payload.chat_history as {
      items: Array<{ created_at: number }>;
    };
    expect(serializedHistory.items[0]?.created_at).toBe(1787458002.314);
  });

  it('serializes the full chat history to the Python snake_case wire format', () => {
    // Mirrors the camelCase fixtures snapshotted in chat_context.test.ts, but asserts the
    // *converted* output: `chat_history` is what the report layer (toSnakeCaseDeep) emits, so
    // this locks down the js->python field mapping for every chat-item type — message,
    // multimodal content (image/audio), function_call (args->arguments), and
    // function_call_output (isError->is_error).
    const chatHistory = new ChatContext();

    chatHistory.addMessage({
      id: 'msg_user_1',
      role: 'user',
      content: [
        'Check out this image and audio:',
        {
          id: 'img_test_1',
          type: 'image_content',
          image: 'https://example.com/test-image.jpg',
          inferenceDetail: 'high',
          inferenceWidth: 1024,
          inferenceHeight: 768,
          mimeType: 'image/jpeg',
          _cache: {},
        } satisfies ImageContent,
        {
          type: 'audio_content',
          frame: [],
          transcript: 'This is a test audio transcript',
        } satisfies AudioContent,
      ],
      createdAt: 3000000000,
    });

    chatHistory.insert(
      new FunctionCall({
        id: 'func_call_1',
        callId: 'call_weather_123',
        name: 'get_weather',
        args: '{"location": "Paris, France", "unit": "celsius"}',
        groupId: 'grp_1',
        thoughtSignature: 'sig_abc',
        createdAt: 3000000001,
      }),
    );

    chatHistory.insert(
      new FunctionCallOutput({
        id: 'func_output_1',
        callId: 'call_weather_123',
        name: 'get_weather',
        output: '{"temperature": 22, "condition": "partly cloudy"}',
        isError: false,
        createdAt: 3000000002,
      }),
    );

    chatHistory.addMessage({
      id: 'msg_assistant_1',
      role: 'assistant',
      content: 'It is 22°C and partly cloudy in Paris.',
      interrupted: false,
      createdAt: 3000000003,
    });

    chatHistory.insert(
      new AgentHandoffItem({
        id: 'item_handoff_1',
        oldAgentId: 'agent_greeter',
        newAgentId: 'agent_booking',
        createdAt: 3000000004,
      }),
    );

    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory,
      enableRecording: false,
      timestamp: 0,
      startedAt: 0,
    });

    const payload = sessionReportToJSON(report);
    expect(payload.chat_history).toMatchSnapshot('chat-history-python-wire');
  });

  it('exports AgentSessionUsage from the voice barrel', () => {
    const usage: AgentSessionUsage = { modelUsage: [] };
    const eventType: AgentSessionEventTypes = AgentSessionEventTypes.SessionUsageUpdated;
    expect(usage.modelUsage).toEqual([]);
    expect(eventType).toBe('session_usage_updated');
  });
});

describe('sessionReportToJSON close_reason', () => {
  function closeReasonFor(reason: string): unknown {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [createCloseEvent(reason)],
      chatHistory: ChatContext.empty(),
    });
    return sessionReportToJSON(report).close_reason;
  }

  it('maps every SDK close reason to a proto value other than CR_UNKNOWN', () => {
    for (const reason of Object.values(CloseReason)) {
      const name = closeReasonFor(reason);
      expect(name).not.toBe('CR_UNKNOWN');
      expect(pb.CloseReason[name as keyof typeof pb.CloseReason]).toBeDefined();
    }
  });

  it('maps custom shutdown reasons to CR_UNKNOWN', () => {
    expect(closeReasonFor('my_custom_reason')).toBe('CR_UNKNOWN');
    // matches a proto value name, but is not an SDK reason
    expect(closeReasonFor('completed')).toBe('CR_UNKNOWN');
  });

  it('maps task_completed to CR_COMPLETED', () => {
    expect(closeReasonFor('task_completed')).toBe('CR_COMPLETED');
  });
});

describe('sessionReportToJSON duration_ms', () => {
  it('is the session length even when recording started earlier', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory: ChatContext.empty(),
      audioRecordingStartedAt: 1_000,
      startedAt: 6_000,
      timestamp: 66_000,
    });
    expect(report.duration).toBe(65_000);
    expect(sessionReportToJSON(report).duration_ms).toBe(60_000);
  });
});

describe('createSessionReport', () => {
  function makeReport(recordingOptions: ResolvedRecordingOptions) {
    const options = baseOptions();
    options.recordingOptions = recordingOptions;
    return createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options,
      events: [],
      chatHistory: ChatContext.empty(),
    });
  }

  it('sets duration without audio recording', () => {
    const report = createSessionReport({
      jobId: 'job',
      roomId: 'room-id',
      room: 'room',
      options: baseOptions(),
      events: [],
      chatHistory: ChatContext.empty(),
      startedAt: Date.now() - 5000,
    });

    expect(report.audioRecordingStartedAt).toBeUndefined();
    expect(report.duration).toBeDefined();
    expect(report.duration).toBeGreaterThan(0);
  });

  it('includes recording options in report options and serializes a defensive copy', () => {
    const recordingOptions: ResolvedRecordingOptions = {
      audio: false,
      traces: false,
      logs: true,
      transcript: false,
      redaction: true,
      inputDelta: false,
    };
    const report = makeReport(recordingOptions);
    expect(report.options.recordingOptions).toEqual(recordingOptions);

    const serializedRecordingOptions = (
      sessionReportToJSON(report).options as Record<string, unknown>
    ).recording_options as ResolvedRecordingOptions;
    expect(serializedRecordingOptions).toEqual(recordingOptions);

    serializedRecordingOptions.audio = true;
    expect(report.options.recordingOptions.audio).toBe(false);
  });
});
